M = "micro-virol-7"
SUB = "Virology"
T = {
"rabies-struct": [
 ("The characteristic bullet shape of the rabies virion is produced when the nucleocapsid associates with the:",["M matrix protein","G glycoprotein","N nucleoprotein","L protein"],0,"M lies between envelope and nucleocapsid, and binding to it makes the nucleocapsid coil into its condensed form."),
 ("Rabies virus buds efficiently from the plasma membrane in only one tissue, which is why that tissue spreads the disease:",["The salivary gland","The cornea","The adrenal medulla","The pancreas"],0,"In most cells the virus buds from intracytoplasmic membranes and release is inefficient.",2),
 ("Transcription of the rabies genome into its five messenger RNAs takes place in:",["Negri bodies","The nucleus","The Golgi apparatus","Viroplasms"],0,"The polymerase is the L and NS proteins, carried into the cell as part of the nucleocapsid.",2),
 ("Which rabies protein generates neutralising antibody?",["The G glycoprotein","The M matrix protein","The N nucleoprotein","The L large protein"],0,"It covers the surface as a trimeric spike and is the viral attachment protein; that of vesicular stomatitis virus was the prototype for studying eukaryotic glycoprotein processing.")],
"rabies-dis": [
 ("Rabies virus reaches the spinal cord from a bite wound by:",["Retrograde axoplasmic transport","Lymphatic spread","Viraemia","Direct extension through fascia"],0,"It first replicates quietly in muscle at the site of the bite for days to months.",2),
 ("The length of the rabies incubation period is determined mainly by:",["Infectious dose and proximity of the wound to the brain","Whether the biting animal was wild or domestic","The blood group of the bitten patient","The ambient temperature at the time"],0,"Severity of the wound and the host's age and immune status also contribute.",2),
 ("Post-exposure vaccination can still prevent rabies because:",["Antibody blocks spread to the central nervous system during the long incubation period","The vaccine is a live virus that outcompetes the wild strain in nerves","Rabies virus is cleared by cell-mediated immunity once primed","The virus is unable to cross the blood-brain barrier"],0,"Neutralising antibody does not appear naturally until clinical disease is well established, by which time the outcome is fatal.",3),
 ("Despite extensive involvement of the brain, histology in rabies shows little beyond:",["Negri bodies","Granulomas","Perivascular cuffing","Demyelination"],0,"Viral proteins inhibit apoptosis and aspects of interferon action, and little antigen is released, so the infection stays largely hidden.",2),
 ("In the United States, rabies is now found more often in cats than dogs because:",["Cats are not vaccinated","Cats hunt infected rodents","Dogs are naturally resistant","Cat saliva carries more virus"],0,"The dog vaccination programme means sylvatic and bat exposure accounts for most animal rabies there; worldwide the dog remains the principal reservoir."),
 ("Worldwide rabies deaths are estimated at:",["40,000 to 100,000 a year","400 to 1000 a year","Fewer than 100 a year","About 2 million a year"],0,"Most are children, and at least 20,000 occur in India, where dogs transmit 96% of cases.")],
"filo": [
 ("Ebola virus enters cells by binding Niemann-Pick C1 and:",["T-cell immunoglobulin and mucin domain 1, also the hepatitis A virus receptor","Intercellular adhesion molecule-1, which rhinoviruses also use","CD150, the signaling lymphocyte-activation molecule","Sialic acid on surface glycoproteins and glycolipids"],0,"Niemann-Pick C1 is a cholesterol transfer protein; replication is in the cytoplasm as in rhabdoviruses.",2),
 ("Filovirus virions differ from rhabdovirus virions in being:",["Long filaments 800 to 1400 nm in length","Icosahedral and without an envelope","Segmented into several nucleocapsids","Smaller than 50 nm in diameter"],0,"They may contain no genome, one, or several."),
 ("Specimens from a patient with suspected filovirus infection require:",["Biosafety level 4 isolation procedures","Level 2 handling with a surgical mask","No special handling once the sample is fixed","Refrigeration during transport only"],0,"RT-PCR of the genome in secretions both confirms the diagnosis and minimises handling of samples.",2),
 ("The rVSV-ZEBOV vaccine used in the 2018 Democratic Republic of Congo outbreak works by:",["Making vesicular stomatitis virus express the Ebola glycoprotein instead of its own","Delivering whole inactivated Ebola virus with an adjuvant","Expressing the Ebola nucleoprotein in a recombinant poxvirus vector","Supplying monoclonal antibody against the glycoprotein"],0,"Health workers and contacts around each outbreak were immunised first, an approach called ring vaccination.",2),
 ("Death occurs in up to what proportion of patients with clinically evident Marburg or Ebola disease?",["90%","10%","30%","50%"],0,"The illness begins with headache and myalgia, then nausea, vomiting and diarrhoea, then haemorrhage from multiple sites.")],
"reo-struct": [
 ("Proteolytic cleavage of the reovirus outer capsid in the gut produces the:",["Intermediate or infectious subviral particle","Core particle with its enzymes exposed","Viroplasm within the cytoplasm","Provirion awaiting its envelope"],0,"Cleavage activates the virus for infection rather than destroying it.",2),
 ("The double-stranded RNA of a reovirus:",["Never leaves the core","Is exported to the nucleus","Is copied by a host polymerase","Is translated directly"],0,"Core enzymes transcribe each negative-sense strand into individual messenger RNAs, which then leave the core."),
 ("The 5'-methyl guanosine cap of messenger RNA was first discovered in:",["Reovirus messenger RNA","Cultured human liver cells","Yeast messenger RNA","Influenza virus transcripts"],0,"It was shown to occur in cellular messenger RNA afterwards."),
 ("Rotavirus VP4 is activated by cleavage into VP5 and VP8, exposing a structure resembling:",["The fusion protein of paramyxoviruses","Influenza neuraminidase spikes","A bacterial adhesin of the pilus","The hepatitis B surface antigen"],0,"Cleaved VP4 lets the virion penetrate the plasma membrane directly.",3),
 ("Reovirus and rotavirus can generate hybrid viruses in a mixed infection because:",["The genome is segmented and segments reassort","Their polymerase recombines whole strands","They integrate into the host chromosome","They exchange capsids during assembly"],0,"This is the same mechanism that produces pandemic influenza strains.",2),
 ("Reoviruses survive in detergents, over wide pH and temperature ranges, and in aerosols because they:",["Are non-enveloped with a double-layered protein capsid","Form spores under adverse conditions","Carry a lipid coat that resists bile","Replicate only at 33 degrees in the upper airway"],0,"The outer capsid also protects the core from gastric acid.")],
"rota": [
 ("Before vaccination, rotavirus accounted for roughly what share of childhood diarrhoea needing hospital admission for dehydration?",["50%","5%","15%","90%"],0,"In underdeveloped countries it caused at least a million deaths a year in undernourished children."),
 ("Rotavirus diarrhoea is described as resembling that of:",["Cholera","Shigellosis","Amoebic dysentery","Giardiasis"],0,"Treatment is supportive rehydration; diagnosis is ELISA for virus in stool.",2),
 ("The oral live rotavirus vaccine is given at:",["2, 4 and 6 months of age","At birth and at 1 month","At 1 year and at 4 years","At 12 and at 18 months"],0,"Newer vaccines are safer than the earlier ones and have reduced disease worldwide."),
 ("Colorado tick fever is caused by a member of the Reoviridae and presents as:",["A dengue-like febrile zoonosis with rash","Bloody diarrhoea with tenesmus","Acute flaccid paralysis of a limb","Jaundice with black vomit and renal failure"],0,"Orbiviruses and coltiviruses are spread by arthropods and are therefore arboviruses.",2)],
"arbo-cycle": [
 ("Most arbovirus infections are limited to the stage of:",["Primary viraemia, with at most mild systemic disease","Local replication at the site of the bite","Secondary viraemia in several organs","Direct invasion of the central nervous system"],0,"Severe systemic disease or encephalitis follows only if enough virus is made during the secondary viraemia to reach critical target tissues.",3),
 ("The flu-like prodrome and the arthritis of arbovirus infection are caused by:",["The interferon and cytokine response","Direct viral lysis of synovium","Vascular thrombosis","Bacterial superinfection"],0,"Complement and cell-mediated responses then contribute to the tissue destruction of encephalitis.",2),
 ("Haemorrhagic symptoms in arbovirus disease arise when:",["Immune complexes and cell-associated antibody activate complement and disrupt vascular cells","Clotting factors are consumed by an anticoagulant in the arthropod vector's saliva","The virus encodes a haemolysin that destroys erythrocytes","Platelets are directly infected and then destroyed"],0,"So the disease is a combination of immune and viral pathogenesis.",3),
 ("A disease spread by animals or with an animal reservoir is called a:",["Zoonosis","Anthroponosis","Nosocomial infection","Sapronosis"],0,"Arboviruses have a very broad host range across vertebrates and invertebrates.")],
"alpha": [
 ("The alphavirus envelope takes on the shape of the capsid because:",["The glycoprotein carboxy terminus is anchored in the capsid, shrink-wrapping the envelope","Matrix protein cross-links the capsid and the envelope into one rigid shell","The capsid is flexible and takes the shape of the envelope","The envelope contains no lipid and so cannot bend"],0,"Two or three glycoproteins associate to form a single spike.",3),
 ("Alphaviruses can be grouped and distinguished by antigenic determinants on their:",["Envelope glycoproteins","Capsid proteins alone","Polymerase sequence","Genomic RNA length"],0,"Capsid proteins of all alphaviruses are similar in structure and antigenically cross-reactive, so they cannot separate them.",2),
 ("Which are alphaviruses?",["Western, eastern and Venezuelan equine encephalitis viruses","Dengue, yellow fever and Japanese encephalitis viruses","St. Louis and West Nile viruses","La Crosse and Hantaan viruses"],0,"They are zoonoses with a reservoir in birds and Aedes and Culex mosquitoes as vectors."),
 ("Compared with picornaviruses, alphaviruses are:",["Slightly larger and enveloped","Smaller and naked","The same size but segmented","Much larger with a helical capsid"],0,"They are 45 to 75 nm; toga is Latin for cloak.")],
"rubella": [
 ("Rubella differs from the other togaviruses in that it:",["Is a respiratory virus with no readily detectable cytopathologic effect","Has a negative-sense genome and carries its own polymerase","Is spread by Aedes and Culex mosquitoes","Has no envelope around its nucleocapsid"],0,"Humans are its only host and it spreads in respiratory secretions.",2),
 ("The fetus is at major risk in maternal rubella until:",["The 20th week of pregnancy","The 8th week of pregnancy","The 30th week of pregnancy","Term, throughout pregnancy"],0,"Maternal immunity from prior exposure or vaccination prevents spread of virus to the fetus.",2),
 ("The most common manifestations of congenital rubella are:",["Cataracts, mental retardation, cardiac abnormalities and deafness","Chorioretinitis and periventricular calcification of the brain","Limb hypoplasia and scarring of the skin","Hydrops fetalis with severe anaemia"],0,"Norman McAlister Gregg linked maternal rubella to congenital cataracts in 1941, which prompted the childhood vaccination programme.",3),
 ("Since the vaccine era, the commonest infectious cause of congenital defects is:",["Cytomegalovirus","Rubella virus","Parvovirus B19","Varicella-zoster virus"],0,"Rubella held that place before vaccination.",2),
 ("Rubella virus was first isolated in 1962 by exploiting the fact that its replication:",["Blocks the replication of superinfecting picornaviruses","Lyses monkey kidney cells in a distinctive pattern","Produces a haemagglutinin on the cell surface","Forms syncytia in the infected monolayer"],0,"That property is called heterologous interference; rubella is not itself cytolytic.",3),
 ("Rubella in an adult, unlike in a child, may include:",["Arthralgia and arthritis","Flaccid paralysis of a limb","Jaundice and dark urine","Parotitis and orchitis"],0,"Rarely there is thrombocytopenia or postinfectious encephalopathy; the rash and joint pain are immune-complex effects.",2)],
"flavi": [
 ("Dengue haemorrhagic fever is worsened by prior infection with another dengue strain because non-neutralising antibody:",["Enhances uptake of the virus into cells bearing Fc receptors","Fixes complement onto the surface of the erythrocytes","Blocks interferon production by infected cells","Causes direct lysis of vascular endothelium"],0,"Cross-reactive antibodies are produced between different flaviviruses, so the response to a related strain can exacerbate immunopathogenesis.",3),
 ("Which flaviviruses cause encephalitis?",["St. Louis, West Nile and Japanese encephalitis viruses","Dengue and yellow fever viruses","Eastern and western equine encephalitis viruses","Hantaan and Lassa viruses"],0,"The haemorrhagic flaviviruses target vasculature, liver and other organs instead of neurons."),
 ("Jaundice and black vomit are the classic picture of:",["Yellow fever","Dengue fever","West Nile fever","Colorado tick fever"],0,"An attenuated live vaccine is available for it.",2),
 ("Hepatitis C virus belongs to which family?",["Flaviviridae","Togaviridae","Reoviridae","Bunyaviridae"],0,"The Flaviviridae include flaviviruses, pestiviruses and the hepaciviruses hepatitis C and G.")],
"bunya": [
 ("Bunyaviruses are unique among negative-strand RNA viruses in lacking:",["A matrix protein","A polymerase","An envelope","A nucleoprotein"],0,"The envelope carries G1 and G2 and encloses the L, M and S segments.",2),
 ("Bunyaviruses prime messenger RNA synthesis by cap-snatching, but unlike influenza they do it:",["In the cytoplasm","In the nucleus","In the Golgi","Inside the virion core"],0,"Virions then assemble by budding into the Golgi rather than at the plasma membrane.",3),
 ("Humans acquire hantavirus by:",["Inhaling aerosols of infected rodent urine","Eating food contaminated by rodents","The bite of an infected mosquito","The bite of an infected tick"],0,"Rodents are both reservoir and vector for hantaviruses, unlike the other bunyaviruses, and shed virus in urine for long periods.",2),
 ("Hantavirus pulmonary syndrome kills by:",["Disrupting endothelial function so the vasculature leaks, with cytolytic immune destruction of tissue","Occluding the pulmonary arterioles with widespread fibrin and platelet microthrombi","Direct lysis of the alveolar lining cells","Secreting a pore-forming toxin in the lung"],0,"The virus replicates in the vasculature and kidneys but is not itself cytolytic.",3),
 ("Many Bunyaviridae persist in one locality year after year because they:",["Survive the winter in mosquito eggs","Infect migratory birds","Form latent infections in humans","Resist desiccation as virions"],0,"Humans who enter the vector's environment are usually dead-end hosts.",2),
 ("The 1993 Four Corners outbreak of hantavirus pulmonary syndrome followed:",["A rise in the deer mouse population after unusually heavy rainfall","Contamination of a municipal water supply by rodent urine","Importation of infected African monkeys","A lapse in the local mosquito control"],0,"Viruses of the Sin Nombre subfamily were isolated from victims and from rodents.",2)],
"arena": [
 ("Arenavirus virions characteristically contain:",["Non-functional host ribosomes","A reverse transcriptase enzyme","Double-stranded RNA segments","A matrix protein layer"],0,"They are medium-sized enveloped viruses with a negative-sense segmented genome that replicate in the cytoplasm.",2),
 ("Lassa fever virus and lymphocytic choriomeningitis virus are both acquired by:",["Inhaling aerosols from rodent urine or faeces","Spread person to person in respiratory droplets","The bite of an infected mosquito","Ingesting undercooked meat"],0,"Rodent control is the preventive measure; Lassa fever is African while lymphocytic choriomeningitis virus is worldwide.",2),
 ("Lymphocytic choriomeningitis virus characteristically causes:",["Meningitis","Haemorrhagic fever","Encephalitis with flaccid paralysis","Pneumonia"],0,"Lassa fever virus is the arenavirus that causes haemorrhagic fever.")],
}
